    #[test]
    fn applies_file_and_env_and_cli_precedence() {
        let mut config = AppConfig::default();

        let file = FileConfig {
            agent: Some(FileAgentConfig {
                max_steps: Some(10),
                memory: None,
            }),
            ..FileConfig::default()
        };
