        let env = EnvOverrides::from_pairs(vec![(
            "MBUS_LLM_MODE".to_string(),
            "openai".to_string(),
        )])
        .expect("env overrides");
        assert_eq!(env.inner.llm_mode, Some(LlmMode::OpenAi));
    }

